using System.ComponentModel.DataAnnotations;using ArcaneVault.Web.Models;using ArcaneVault.Web.Services;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;
namespace ArcaneVault.Web.Pages.Categories;
public class EditCategoryModel(ApiClient api):PageModel{[BindProperty]public string Code{get;set;}="";[BindProperty,Required,StringLength(60),Display(Name="Category name")]public string CategoryName{get;set;}="";public async Task<IActionResult>OnGetAsync(string code){var c=await api.GetAsync<CategoryDto>($"api/categories/{code}");if(c is null)return NotFound();Code=c.CategoryCode;CategoryName=c.CategoryName;return Page();}public async Task<IActionResult>OnPostAsync(){if(!ModelState.IsValid)return Page();try{await api.PutAsync($"api/categories/{Code}",new{CategoryCode=Code,CategoryName});TempData["Success"]="Category updated.";return RedirectToPage("Details",new{code=Code});}catch(ApiException ex){ModelState.AddModelError("",ex.Message);return Page();}}}
